app.config['JWT_SECRET_KEY'] = 'super-secret-key'
app.config['JWT_ACCESS_TOKEN_EXPIRES'] = timedelta(minutes=15)
app.config['JWT_REFRESH_TOKEN_EXPIRES'] = timedelta(days=7)

# Redis connection
redis_client = Redis(host='localhost', port=6379, decode_responses=True)

# Logging
logging.basicConfig(
    filename='/app/logs/app.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)

# Load test user
TEST_USER = {
    'username': 'admin',
    'password_hash': generate_password_hash('password123', method='bcrypt')
}


def get_redis_blacklist_key(jti):
    return f'blacklist:{jti}'


def check_token_validity(token, token_type='access'):
    """Check if a token is valid (not expired, not revoked)."""
    try:
        # Get the token claims
        payload = jwt.decode(
            token,
            options={"verify_signature": False},
            algorithms=["RS256"]
        )
        jti = payload.get('jti')
        if not jti:
            return False, "Missing JTI"

        # Check expiration
        exp = payload.get('exp')
        if exp and datetime.utcnow().timestamp() > exp:
            return False, "Expired"

        # Check blacklist
        blacklist_key = get_redis_blacklist_key(jti)
        if redis_client.exists(blacklist_key):
            return False, "Revoked"

        return True, "Valid"
    except InvalidTokenError:
        return False, "Invalid"
    except Exception as e:
        logger.error(f"Error checking token: {e}")
        return False, "Error"


@app.route('/auth/login', methods=['POST'])
