    data = request.get_json()
    username = data.get('username')
    password = data.get('password')

    if username != TEST_USER['username']:
        return jsonify({"error": "Invalid credentials"}), 401

    if not check_password_hash(TEST_USER['password_hash'], password):
        return jsonify({"error": "Invalid credentials"}), 401

    # Create tokens with unique JTI
    access_token = create_access_token(
        identity=username,
        fresh=True,
        additional_claims={"jti": os.urandom(16).hex()}
    )
    refresh_token = create_refresh_token(
        identity=username,
        additional_claims={"jti": os.urandom(16).hex()}
    )

    # Save to tokens.json
    tokens = {
        "access_token": access_token,
        "refresh_token": refresh_token
    }
    with open('/app/tokens.json', 'w') as f:
        json.dump(tokens, f)

    return jsonify(tokens), 200


@app.route('/auth/refresh', methods=['POST'])
def refresh():
    data = request.get_json()
    refresh_token = data.get('refresh_token')

    if not refresh_token:
        return jsonify({"error": "Missing refresh token"}), 400

    try:
        # Verify the refresh token
        payload = jwt.decode(
            refresh_token,
            options={"verify_signature": True},
            algorithms=["RS256"]
        )
        jti = payload.get('jti')

        # Check if token is valid
        valid, reason = check_token_validity(refresh_token, token_type='refresh')
        if not valid:
